namespace GitExtensions.GitLab.Api.Models;

public sealed class Note
{
    public long Id { get; init; }
    public string Body { get; init; } = "";
    public User Author { get; init; } = new();
    public DateTimeOffset CreatedAt { get; init; }

    /// <summary>
    ///  Notes generated by GitLab ("added 1 commit", "approved this merge request", ...).
    /// </summary>
    public bool System { get; init; }
}

public sealed class Approvals
{
    public bool Approved { get; init; }
    public int? ApprovalsRequired { get; init; }
    public int? ApprovalsLeft { get; init; }
    public bool UserHasApproved { get; init; }
    public bool UserCanApprove { get; init; }
    public IReadOnlyList<Approver> ApprovedBy { get; init; } = [];
}

public sealed class Approver
{
    public User User { get; init; } = new();
}
